 5	public class ActivitySelection {
 6	    private static final Comparator<Activity> BY_FINISH_TIME =
 7	        Comparator.comparingInt(Activity::finishTime);
 8	
 9	    private ActivitySelection() {
10	    }
11	
12	    public static int activitySelection(int[] start, int[] finish) {
13	        return countSelectedActivities(sortByFinishTime(buildActivities(start, finish)));
14	    }
15	
16	    private static Activity[] buildActivities(int[] start, int[] finish) {
17	        Objects.requireNonNull(start, "start must not be null");
18	        Objects.requireNonNull(finish, "finish must not be null");
19	
20	        if (start.length != finish.length) {
21	            throw new IllegalArgumentException("start and finish must have the same length");
22	        }
23	
24	        Activity[] activities = new Activity[start.length];
25	        for (int i = 0; i < start.length; i++) {
26	            activities[i] = new Activity(start[i], finish[i]);
27	        }
28	        return activities;
29	    }
30	
31	    private static Activity[] sortByFinishTime(Activity[] activities) {
32	        Arrays.sort(activities, BY_FINISH_TIME);
33	        return activities;
34	    }
35	
36	    private static int countSelectedActivities(Activity[] activities) {
37	        if (activities.length == 0) {
38	            return 0;
39	        }
40	
41	        int count = 1;
42	        Activity lastSelected = activities[0];
43	
44	        // Greedily keep the earliest-finishing compatible activity.
45	        for (int i = 1; i < activities.length; i++) {
46	            Activity current = activities[i];
47	            if (current.canFollow(lastSelected)) {
48	                count++;
49	                lastSelected = current;
50	            }
51	        }
52	
53	        return count;
54	    }
55	
56	    public static void main(String[] args) {
57	        int[] start = {1, 3, 0, 5, 8, 5};
58	        int[] finish = {2, 4, 6, 7, 9, 9};
59	
60	        System.out.println(activitySelection(start, finish));
61	    }
62	
63	    private static final class Activity {
64	        private final int startTime;
65	        private final int finishTime;
66	
67	        private Activity(int startTime, int finishTime) {
68	            this.startTime = startTime;
69	            this.finishTime = finishTime;
70	        }
71	
72	        private int finishTime() {
73	            return finishTime;
74	        }
75	
76	        private boolean canFollow(Activity other) {
77	            return startTime > other.finishTime;
78	        }
79	    }
80	}

